import {test,expect} from '@playwright/test';
import jsQR from 'jsqr';
import {PNG} from 'pngjs';
test('genética reutilizável, persistência, histórico e etiquetas com QR decodificável',async({page})=>{
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto('/');
 await page.getByRole('button',{name:/Banco de Genéticas/}).click();
 await page.getByRole('button',{name:'+ Cadastrar genética',exact:true}).click();
 await page.getByLabel('Nome da genética *',{exact:true}).fill('Genética A');
 await page.getByLabel('Floração anunciada: mínimo').fill('8');
 await page.getByLabel('Floração anunciada: máximo').fill('10');
 await page.getByRole('button',{name:'Salvar genética',exact:true}).click();
 await page.getByRole('button',{name:/Minhas plantas/}).click();
 for(const name of ['Planta A','Planta B']){
  await page.getByRole('button',{name:'+ Cadastrar planta',exact:true}).click();
  await page.getByLabel('Nome da planta *').fill(name);
  await page.getByLabel('Data de início *',{exact:true}).fill('2026-01-01');
  await page.getByLabel('Genética (opcional)').selectOption({label:'Genética A'});
  await page.getByRole('button',{name:'Salvar planta',exact:true}).click();
 }
 await page.reload();
 const card=page.locator('article').filter({has:page.getByRole('heading',{name:'Planta A',exact:true})});
 await expect(card).toContainText('Genética A');
 await card.getByRole('button',{name:'Editar planta'}).click();
 await page.getByLabel('Fase atual *').selectOption('Vega');
 await page.getByLabel('Data da mudança de fase').fill('2026-02-01');
 await page.getByRole('button',{name:'Salvar planta',exact:true}).click();
 await card.locator('summary').click();
 await expect(card).toContainText('Broto · 01/01/2026');await expect(card).toContainText('Vega · 01/02/2026');
 await page.getByRole('button',{name:/Banco de Genéticas/}).click();
 await page.getByRole('button',{name:'Editar genética'}).click();
 await page.getByLabel('Nome da genética *',{exact:true}).fill('Genética revisada');
 await page.getByRole('button',{name:'Salvar genética',exact:true}).click();
 await expect(page.locator('article')).toContainText('2 planta(s) associada(s)');
 await page.getByRole('button',{name:/Minhas plantas/}).click();
 await expect(card).toContainText('Genética revisada');
 await page.evaluate(()=>{window.print=()=>{window.printCalled=true;};});
 await card.getByRole('button',{name:'Imprimir QR',exact:true}).click();
 await expect.poll(()=>page.evaluate(()=>window.printCalled)).toBe(true);
 const src=await page.locator('#print-area img').getAttribute('src');
 const png=PNG.sync.read(Buffer.from(src.split(',')[1],'base64'));
 const decoded=jsQR(new Uint8ClampedArray(png.data),png.width,png.height)?.data;
 expect(decoded).toBe(await page.evaluate(()=>`growtrack:planta:${JSON.parse(localStorage.getItem('growtrack.v1')).plants[0].id}`));
 await page.emulateMedia({media:'print'});
 await expect(page.locator('#app')).toBeHidden();await expect(page.locator('.print-label')).toBeVisible();
 expect(errors).toEqual([]);
});
test('mobile, erro de armazenamento e dados corrompidos',async({page})=>{
 await page.setViewportSize({width:360,height:800});await page.goto('/');
 expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);
 await page.getByRole('button',{name:'+ Cadastrar planta',exact:true}).click();
 await page.getByLabel('Nome da planta *').fill('<script>alert(1)</script>');
 await page.evaluate(()=>{Storage.prototype.setItem=()=>{throw new Error('QuotaExceededError');};});
 await page.getByRole('button',{name:'Salvar planta',exact:true}).click();
 await expect(page.getByRole('alert')).toContainText('Não foi possível salvar');
 await expect(page.locator('article')).toHaveCount(0);
 await page.reload();
 await page.evaluate(()=>localStorage.setItem('growtrack.v1','{quebrado'));
 await page.reload();await expect(page.locator('aside')).toContainText('Gravação bloqueada');
 expect(await page.evaluate(()=>localStorage.getItem('growtrack.v1'))).toBe('{quebrado');
});
